-- Ported from monitors.conf (originally generated by nwg-displays).
-- https://wiki.hypr.land/Configuring/Monitors/
--
-- Monitors are matched by description ("desc:...") instead of connector name.
-- The connector names changed after the NVIDIA/Hyprland update (DP-1 -> DP-4,
-- HDMI-A-1 -> HDMI-A-2), which silently broke every rule keyed on the old names.
-- Descriptions come from `hyprctl monitors`.

local ACER    = "desc:Acer Technologies XZ322QU V3 24180D8373W01"    -- was DP-1
local SAMSUNG = "desc:Samsung Electric Company S24F350 H4ZM802678"   -- was HDMI-A-1

hl.monitor({ output = ACER,    mode = "2560x1440@180", position = "0x0",      scale = 1.0 })
hl.monitor({ output = SAMSUNG, mode = "1920x1080@60",  position = "2560x137", scale = 1.0 })

-- Old third output (no longer present); the last line of the old file disabled it.
hl.monitor({ output = "HDMI-A-3", disabled = true })

return { ACER = ACER, SAMSUNG = SAMSUNG }
